import { ConsolidatedPdfGazette, Job } from '../types/job';

export type ScraperFormatType = 
  | 'PDF Advertisement (pdfplumber)'
  | 'Structured HTML Table (BeautifulSoup)'
  | 'Dynamic JavaScript / REST Endpoint'
  | 'ASPX / PHP Secure Form'
  | 'International Remote / NGO Feed';

export type ScraperSector = 
  | 'Federal & Autonomous'
  | 'Provincial & Local / Municipal'
  | 'Law Enforcement & Security'
  | 'Healthcare & Medical'
  | 'Higher Education & Training'
  | 'International & UN Agencies';

export type ScraperJurisdiction = 
  | 'Federal'
  | 'Punjab'
  | 'Sindh'
  | 'Khyber Pakhtunkhwa'
  | 'Balochistan'
  | 'Gilgit-Baltistan'
  | 'AJK'
  | 'Azad Jammu & Kashmir'
  | 'Pakistan'
  | 'International';

export interface ComprehensiveScraperPortal {
  id: string;
  name: string;
  shortName: string;
  portalUrl: string;
  pdfUrl?: string;
  organization: string;
  category: 
    | 'National / Federal Portal'
    | 'Public Service Commission'
    | 'Defence & Armed Forces'
    | 'Autonomous / Public Sector'
    | 'Federal Ministry'
    | 'Provincial Govt & Development'
    | 'Healthcare & Medical Cadres'
    | 'Higher Education & Universities'
    | 'Testing & Assessment Service'
    | 'International & UN Agencies'
    | 'Law Enforcement & Security'
    | 'Municipal & Tehsil Level';
  formatType: ScraperFormatType;
  formatBadge: string;
  sector: ScraperSector;
  jurisdiction: ScraperJurisdiction;
  crawlerMethod: string;
  badge: string;
  description: string;
  typicalScales: string;
  defaultDeadline: string;
  sampleAdvtNo: string;
}

